import { forwardRef, useImperativeHandle, useRef, type CSSProperties, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface ShadowSweepTextProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  backgroundColor?: string;
  shadowColor?: string;
  shadowSoftness?: number;
  rise?: number;
  driftLeft?: number;
  speed?: number;
  className?: string;
}

const shadowSweepTextLength = 37;

const ENTER_END = 23;
const EXIT_START = 26;
const EXIT_END = shadowSweepTextLength - 1;
const REST_X = -20;
const REST_Y = 9;
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

function ShadowSweepTextBase({
  text,
  fontSize = 96,
  color = "#aaa6b5",
  fontWeight = 700,
  backgroundColor = "#030012",
  shadowColor = "#000008",
  shadowSoftness = 130,
  rise = 96,
  driftLeft = 16,
  speed = 1,
  className,
}: ShadowSweepTextProps) {
  const frame = useCurrentFrame() * speed;
  const safeSoftness = Math.max(shadowSoftness, 0);
  const travelProgress = interpolate(
    frame,
    [0, shadowSweepTextLength - 1],
    [0, 1],
    {
      ...clamp,
      easing: Easing.out(Easing.cubic),
    },
  );
  const enterProgress = interpolate(frame, [-3, ENTER_END], [0, 1], clamp);
  const exitProgress = interpolate(
    frame,
    [EXIT_START, EXIT_END],
    [0, 1],
    clamp,
  );
  const x = REST_X + driftLeft * (1 - travelProgress);
  const y = REST_Y + rise * (1 - travelProgress);
  const enterOffset = `calc(${enterProgress * 100}% + ${
    enterProgress * safeSoftness
  }px)`;
  const remainingExit = 1 - exitProgress;
  const exitOffset = `calc(${-remainingExit * 100}% - ${
    remainingExit * safeSoftness
  }px)`;
  const shadowOffset = safeSoftness * 0.45;
  const shadowBlur = safeSoftness * 0.55;
  const shadowSpread = safeSoftness * 0.08;
  const occluderStyle: CSSProperties = {
    position: "absolute",
    inset: "-0.45em -0.8em",
    backgroundColor,
    pointerEvents: "none",
  };

  if (text.length === 0) {
    return (
      <div
        className={className}
        style={{ position: "absolute", inset: 0, backgroundColor }}
      />
    );
  }

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        backgroundColor,
      }}
    >
      <div
        style={{
          position: "relative",
          color,
          fontFamily: "Arial, Helvetica, sans-serif",
          fontSize,
          fontWeight,
          letterSpacing: 0,
          lineHeight: 1,
          opacity: 1,
          transform: `translate3d(${x}px, ${y}px, 0)`,
          whiteSpace: "nowrap",
        }}
      >
        {text}

        <div
          style={{
            ...occluderStyle,
            boxShadow: `${-shadowOffset}px 0 ${shadowBlur}px ${shadowSpread}px ${shadowColor}`,
            display: frame < ENTER_END ? "block" : "none",
            transform: `translate3d(${enterOffset}, 0, 0)`,
          }}
        />
        <div
          style={{
            ...occluderStyle,
            boxShadow: `${shadowOffset}px 0 ${shadowBlur}px ${shadowSpread}px ${shadowColor}`,
            display: frame >= EXIT_START ? "block" : "none",
            transform: `translate3d(${exitOffset}, 0, 0)`,
          }}
        />
      </div>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "are abandoned",
    description: "Text",
  },
  fontSize: {
    type: "number",
    min: 24,
    max: 180,
    step: 1,
    default: 96,
    description: "Font size",
    hiddenFromList: false,
  },
  rise: {
    type: "number",
    min: 0,
    max: 300,
    step: 1,
    default: 96,
    description: "Vertical travel",
    hiddenFromList: false,
  },
  driftLeft: {
    type: "number",
    min: 0,
    max: 120,
    step: 1,
    default: 16,
    description: "Leftward travel",
    hiddenFromList: false,
  },
  shadowSoftness: {
    type: "number",
    min: 0,
    max: 280,
    step: 2,
    default: 130,
    description: "Shadow softness",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#aaa6b5",
    description: "Text color",
  },
  backgroundColor: {
    type: "color",
    default: "#030012",
    description: "Background color",
  },
  shadowColor: {
    type: "color",
    default: "#000008",
    description: "Shadow color",
  },
  fontWeight: {
    type: "enum",
    default: "700",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","fontSize","rise","driftLeft","shadowSoftness","color","backgroundColor","shadowColor","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "are abandoned",
  fontSize: 96,
  rise: 96,
  driftLeft: 16,
  shadowSoftness: 130,
  color: "#aaa6b5",
  backgroundColor: "#030012",
  shadowColor: "#000008",
  fontWeight: "700",
  speed: 1,
};

type ShadowSweepTextElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShadowSweepTextBase>;

const ShadowSweepTextInner = forwardRef<
  HTMLDivElement,
  ShadowSweepTextElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShadowSweepText>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShadowSweepTextBase
          {...(componentProps as unknown as ComponentProps<typeof ShadowSweepTextBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShadowSweepText = Interactive.withSchema({
  Component: ShadowSweepTextInner,
  componentName: "<ShadowSweepText>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
